UPDATE companies SET description='While a founding year is not publicly disclosed, Chad describes himself as a family man who began the venture to create enduring, handcrafted furniture rather than pursue high-volume sales.

The shop produces custom wooden furniture using traditional joinery techniques, emphasizing the natural integrity of each piece. Chad handles design, construction, and client consultation personally, working primarily with locally sourced wood when possible. The operation is scaled for one-off commissions and small batches, with no published facility size or employee count.

Projects range from dining tables and rocking chairs to porch swings, each developed through an initial consultation and detailed cost analysis. Clients are encouraged to visit the shop during the build process.

Chad founded the business to counter the trend of disposable, mass-produced furniture, aiming to build pieces that become cherished household fixtures. The differentiators he cites include traditional joinery, a collaborative design process, and a commitment to local materials.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Traditional joinery", "Hand crafting", "Client consultation", "Cost analysis", "In-process shop visits"], "industries": ["Custom furniture manufacturing", "Residential furniture", "Woodworking", "Mid-century modern furniture"], "materials": ["Wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Traditional joinery construction", "Custom design consultation with detailed cost analysis", "Shop visits encouraged during production", "Local materials sourced when possible", "Mid-century modern design focus"], "facts_used": ["Location: Salt Lake City, Utah -> db", "Founder: Chad -> /about", "Product: Custom handcrafted wooden furniture -> /about", "Process: Traditional joinery -> /about", "Materials: Wood, local materials when possible -> /about", "Style focus: Mid-century modern -> /about", "Customer consultation and shop visits -> /about", "Philosophy: Quality, durability, not mass-produced -> /about", "Family-owned -> / (description)"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "hand crafted wooden furniture represents the peculiarity of people and their homes", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='furniture-joint' AND approved AND profile IS NULL;
UPDATE companies SET description='G&G Industries was established in 1992 in Shelby Township, Michigan. The company began as a fabric die cutter and converter before expanding into automotive interior components.

The company specializes in honeycomb composite spray molding (CSM) for automotive interior trim and NVH components, including load floors, sunshade assemblies, and compression-molded parts. Operating from a 70,000-square-foot facility, G&G produces more than 1.3 million composite panels annually and supports production programs ranging from 10,000 to 500,000 units.

G&G serves automotive OEMs and Tier 1 suppliers, with its parts found in vehicles from Subaru, BMW, Mercedes-Benz, General Motors, Lexus, Toyota, Stellantis (FCA), Ford, Nissan, and Honda.

G&G was the first in North America to introduce honeycomb composite spray molding to the automotive industry in 2004 and the first to produce load floors using polyurethane CSM technology in 2007. The company emphasizes quality-driven processes, program management, and on-time delivery as core differentiators.', certifications=ARRAY['IATF 16949:2016','ISO/TS 16949:2009','QS9000']::text[], profile='{"capabilities": ["Honeycomb Composite Spray Molding", "Insert Molding", "Multiple honeycomb core material & design options", "Mechanical Engineering", "Program Management", "Manufacturing Engineering", "Design Capabilities", "Lean Manufacturing Techniques", "Material Resource Planning", "Production Planning", "Product & Process Design", "Waterjet Cutting", "Stamping/Blanking", "Pinch Trim in Mold", "Automated and manual Lamination of textiles to substrates", "Lamination of high-value decorative fabrics and non-wovens", "Thermal Film Lamination", "Roll Coat Adhesive Lamination", "Spray Adhesive Lamination", "Edge-wrapping", "Die Cutting", "Honeycomb Expansion", "Automotive Interior Color Matching and Evaluation", "In-house Calibrated Premium Light Booth"], "industries": ["Automotive"], "materials": ["Polyurethane", "Paper honeycomb", "Textiles", "Decorative fabrics", "Non-wovens", "Films", "Foils", "Carpet"], "equipment": ["4 CSM cells with 10 dedicated presses", "2 converting presses", "2 honeycomb expanders", "Waterjet cutting system", "Stamping/blanking equipment", "Pinch trim in-mold capability", "Robotic spray process", "Calibrated premium light booth"], "volume": "10,000 to 500,000 units per program; 1.3+ million panels annually", "lead_time": "", "tolerances": "", "built_on": ["First in North America to introduce honeycomb composite spray molding (2004)", "First to produce load floors using polyurethane CSM technology (2007)", "Over 1.3 million composite panels produced annually", "IATF 16949:2016 certified quality system", "In-house honeycomb expansion and automoti